import sys
import os

subcommands = ['add', 'config-init', 'init', 'copy', 'cp', 'edit', 'help', 'list', 'ls', 'move', 'mv', 'rename', 'remove', 'rm', 'run', 'show']

def parse_main_args(argv):
    args = argv[1:]
    parsed = {
        'config_file': None,
        'verbose': 0,
        'cmd': 'run', # default if not subcommand
        'cmd_args': []
    }

    i = 0
    while i < len(args):
        a = args[i]
        if a in ['-c', '--config-file']:
            parsed['config_file'] = args[i+1]
            i += 2
        elif a in ['-v', '--verbose']:
            parsed['verbose'] += 1
            i += 1
        elif a in ['-h', '--help']:
            parsed['cmd'] = 'help'
            break
        elif a in ['-V', '--version']:
            print("pier 0.1.6")
            sys.exit(0)
        elif not a.startswith('-'):
            if a in subcommands:
                parsed['cmd'] = a
                parsed['cmd_args'] = args[i+1:]
            else:
                parsed['cmd'] = 'run'
                parsed['cmd_args'] = args[i:]
            break
        else:
            sys.stderr.write(f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context\n")
            sys.exit(1)

    return parsed

if __name__ == "__main__":
    print(parse_main_args(sys.argv))
