import sys

def parse_add(args):
    opts = {'force': False, 'alias': None, 'description': None, 'tags': [], 'command': None}
    i = 0
    while i < len(args):
        a = args[i]
        if a in ['-f', '--force']:
            opts['force'] = True
        elif a in ['-a', '--alias']:
            opts['alias'] = args[i+1]
            i += 1
        elif a in ['-d', '--description']:
            opts['description'] = args[i+1]
            i += 1
        elif a in ['-t', '--tag']:
            i += 1
            while i < len(args) and not args[i].startswith('-'):
                opts['tags'].append(args[i])
                i += 1
            continue
        elif not a.startswith('-'):
            if args[i] == '--':
                i += 1
            if i < len(args):
                opts['command'] = args[i]
            break
        else:
            print(f"error: Found argument '{a}' which wasn't expected...")
            sys.exit(1)
        i += 1
    return opts

def parse_list(args):
    opts = {'cmd_full': False, 'list_aliases': False, 'cmd_width': None, 'tags': []}
    i = 0
    while i < len(args):
        a = args[i]
        if a in ['-l', '--cmd_full']:
            opts['cmd_full'] = True
        elif a in ['-q', '--list_aliases']:
            opts['list_aliases'] = True
        elif a in ['-c', '--cmd_width']:
            opts['cmd_width'] = int(args[i+1])
            i += 1
        elif a in ['-t', '--tag']:
            i += 1
            while i < len(args) and not args[i].startswith('-'):
                opts['tags'].append(args[i])
                i += 1
            continue
        else:
            sys.exit(1)
        i += 1
    return opts

# For simple commands like edit, remove, show, run
def parse_simple(args):
    opts = {'alias': None, 'args': []}
    if len(args) > 0:
        opts['alias'] = args[0]
        opts['args'] = args[1:]
    return opts

def parse_copy_move(args):
    opts = {'force': False, 'from': None, 'to': None}
    i = 0
    while i < len(args):
        a = args[i]
        if a in ['-f', '--force']:
            opts['force'] = True
        elif not a.startswith('-'):
            if not opts['from']:
                opts['from'] = a
            else:
                opts['to'] = a
        i += 1
    return opts
