{"command":"cat << 'EOF' > test_toml_writer.py
import json
import pip._vendor.tomli as tomli

def format_val(v):
    if isinstance(v, str):
        return json.dumps(v)
    elif isinstance(v, list):
        items = ",\n    ".join([format_val(x) for x in v])
        if not items:
            return "[]"
        return "[\n    " + items + ",\n]"
    return json.dumps(v)

def write_toml(data, path):
    lines = []

    scripts = data.get("scripts", {})
    for alias in sorted(scripts.keys()):
        alias_formatted = json.dumps(alias) if '.' in alias else alias
        lines.append(f"[scripts.{alias_formatted}]")
        for k in ['command', 'description', 'tags']:
            if k in scripts[alias]:
                v = scripts[alias][k]
                if k == 'tags' and not v:
                    continue
                lines.append(f"{k} = {format_val(v)}")
        lines.append("")

    if "default" in data:
        lines.append("[default]")
        for k, v in data["default"].items():
            lines.append(f"{k} = {format_val(v)}")

    with open(path, "w") as f:
        f.write("\n".join(lines) + "\n")

data = {"scripts": {"my.alias": {"command": "echo \"hello\\n\"", "description": "test", "tags": ["a", "b"]}, "other": {"command": "test"}}, "default": {}}
write_toml(data, "out.toml")

with open("out.toml", "r") as f:
    print(f.read())

with open("out.toml", "rb") as f:
    parsed = tomli.load(f)
    print("Parsed:", parsed)
EOF
