#!/usr/bin/env python3
import sys
import os
import shutil
import tempfile
import subprocess
import json
import pip._vendor.tomli as tomli

def get_config_path_candidates():
    paths = []
    if "PIER_CONFIG_PATH" in os.environ:
        paths.append(os.environ["PIER_CONFIG_PATH"])
    paths.append(os.path.abspath("pier.toml"))

    xdg = os.environ.get("XDG_CONFIG_HOME")
    if not xdg:
        xdg = os.path.join(os.environ.get("HOME", ""), ".config")

    paths.append(os.path.join(xdg, "pier/config.toml"))
    paths.append(os.path.join(xdg, "pier/config"))
    paths.append(os.path.join(xdg, "pier.toml"))

    home = os.environ.get("HOME", "")
    paths.append(os.path.join(home, ".pier.toml"))
    paths.append(os.path.join(home, ".pier"))

    return paths

def get_config_path(cli_path=None, for_creation=False):
    if cli_path:
        return cli_path

    paths = get_config_path_candidates()
    for p in paths:
        if os.path.exists(p):
            return p

    if for_creation:
        if "PIER_CONFIG_PATH" in os.environ:
            return os.environ["PIER_CONFIG_PATH"]
        xdg = os.environ.get("XDG_CONFIG_HOME")
        if not xdg:
            xdg = os.path.join(os.environ.get("HOME", ""), ".config")
        return os.path.join(xdg, "pier/config.toml")
    return None

def format_val(v):
    if isinstance(v, str):
        return json.dumps(v)
    elif isinstance(v, list):
        items = ",\n    ".join([format_val(x) for x in v])
